mapper.select:
select id, protocol_name, protocol_code, protocol_type, version_num, is_enable, create_time, update_time from t_portal_protocol where is_valid = 1
and protocol_name like concat('%',#{query.protocolName},'%')
and protocol_code like concat('%',#{query.protocolCode},'%')
and protocol_type = #{query.protocolType}
and update_time between #{query.updateTimeStart} and #{query.updateTimeEnd}
order by create_time desc
